bool member(const std::uint32_t*list,unsigned int n,std::uint32_t pc){for(unsigned int i=0;i<n;++i)if(list[i]==pc)return true;return false;}
// Generic one-block fixture: zero RAM, STOP at SP/SP+4/SP+8, D0-D7 zero, A0 10e000, A1 10e100 (also the JSR (A1)
// target), A4 10e300, A5 108000, A6 10e900.
void generic(std::uint32_t pc,Bytes&ram,State&s){ram.assign(65536,0);put(ram,SP,4,STOP);put(ram,SP+4,4,STOP);put(ram,SP+8,4,STOP);
 s=State();s.pc=pc;s.carry=ms5::AnimationCarryClear;for(unsigned int i=0;i<8;++i){s.d[i]=0;s.a[i]=0;}
 s.a[0]=0x10e000;s.a[1]=0x10e100;s.a[4]=0x10e300;s.a[5]=A5;s.a[6]=0x10e900;s.a[7]=SP;}

void zero_step(){
 assert(NSTARTS==151&&KEEPS==66);
 for(unsigned int c=0;c<3;++c)for(unsigned int i=0;i<NSTARTS;++i){Bytes ram;State s;generic(STARTS[i],ram,s);s.carry=carry_of(c);
  const Bytes before=ram;const State old=s;Out o;assert(run(ram,s,STARTS[i],o)&&same(s,old)&&ram==before&&quiet(o));}
}
